    { left = guard "left" seed; left_bits = #0xdead_beefl; data = make seed i;
      right_bits = #0x1234_5678_9abc_def0L; right = guard "right" seed }
  let[@inline never] replace cell seed i = cell.data <- make seed i
  let[@inline never] observe cell =
    cell.left, box32 cell.left_bits, read cell.data, box64 cell.right_bits, cell.right
  let () = exercise "V195" [|[Wide; Wide; Narrow]; [Text; Wide]|] ~create ~replace ~observe
end

module V196 = struct
  type payload =
    | K0 of #(int * int64_u)
    | K1 of int * int64_u * int
    | K2 of string * string * #(int64_u * int64_u)
  [@@unboxed]
  type cell = { left : string; left_bits : int32_u; mutable data : payload;
                right_bits : int64_u; right : string }
  let make seed = function
    | 0 -> K0 (#(number seed 0, unbox64 (wide seed 1)))
    | 1 -> K1 (number seed 0, unbox64 (wide seed 1), number seed 2)
    | i -> assert (i = 2); K2 (text seed 0, text seed 1, #(unbox64 (wide seed 2), unbox64 (wide seed 3)))
  let read = function
    | K0 (#(x0, x1)) -> 0, [I x0; I64 (box64 x1)]
    | K1 (x0, x1, x2) -> 1, [I x0; I64 (box64 x1); I x2]
    | K2 (x0, x1, #(x2, x3)) -> 2, [S x0; S x1; I64 (box64 x2); I64 (box64 x3)]
  let[@inline never] create seed i =
    { left = guard "left" seed; left_bits = #0xdead_beefl; data = make seed i;
      right_bits = #0x1234_5678_9abc_def0L; right = guard "right" seed }
  let[@inline never] replace cell seed i = cell.data <- make seed i
  let[@inline never] observe cell =
    cell.left, box32 cell.left_bits, read cell.data, box64 cell.right_bits, cell.right
  let () = exercise "V196" [|[Tagged; Wide]; [Tagged; Wide; Tagged]; [Text; Text; Wide; Wide]|] ~create ~replace ~observe
end

module V197 = struct
  type payload =
    | K0 of #(int * int32_u) * int64_u
    | K1
    | K2 of #(int64_u * string) * float# * float#
    | K3 of #(int * int32_u) * int
  [@@unboxed]
  type cell = { left : string; left_bits : int32_u; mutable data : payload;
                right_bits : int64_u; right : string }
  let make seed = function
    | 0 -> K0 (#(number seed 0, unbox32 (narrow seed 1)), unbox64 (wide seed 2))
    | 1 -> K1
    | 2 -> K2 (#(unbox64 (wide seed 0), text seed 1), unbox_float (fraction seed 2), unbox_float (fraction seed 3))
    | i -> assert (i = 3); K3 (#(number seed 0, unbox32 (narrow seed 1)), number seed 2)
  let read = function
    | K0 (#(x0, x1), x2) -> 0, [I x0; I32 (box32 x1); I64 (box64 x2)]
    | K1 -> 1, []
    | K2 (#(x0, x1), x2, x3) -> 2, [I64 (box64 x0); S x1; F (box_float x2); F (box_float x3)]
    | K3 (#(x0, x1), x2) -> 3, [I x0; I32 (box32 x1); I x2]
  let[@inline never] create seed i =
    { left = guard "left" seed; left_bits = #0xdead_beefl; data = make seed i;
      right_bits = #0x1234_5678_9abc_def0L; right = guard "right" seed }
  let[@inline never] replace cell seed i = cell.data <- make seed i
  let[@inline never] observe cell =
    cell.left, box32 cell.left_bits, read cell.data, box64 cell.right_bits, cell.right
  let () = exercise "V197" [|[Tagged; Narrow; Wide]; []; [Wide; Text; Fraction; Fraction]; [Tagged; Narrow; Tagged]|] ~create ~replace ~observe
end

module V198 = struct
  type payload =
    | K0 of int
    | K1 of #(float# * int64_u)
    | K2 of #(float# * int32_u) * string * float#
    | K3 of #(string * string) * int64_u
    | K4 of #(float# * int64_u) * string * string
  [@@unboxed]
  type cell = { left : string; left_bits : int32_u; mutable data : payload;
                right_bits : int64_u; right : string }
  let make seed = function
    | 0 -> K0 (number seed 0)
    | 1 -> K1 (#(unbox_float (fraction seed 0), unbox64 (wide seed 1)))
    | 2 -> K2 (#(unbox_float (fraction seed 0), unbox32 (narrow seed 1)), text seed 2, unbox_float (fraction seed 3))
    | 3 -> K3 (#(text seed 0, text seed 1), unbox64 (wide seed 2))
    | i -> assert (i = 4); K4 (#(unbox_float (fraction seed 0), unbox64 (wide seed 1)), text seed 2, text seed 3)
  let read = function
    | K0 (x0) -> 0, [I x0]
    | K1 (#(x0, x1)) -> 1, [F (box_float x0); I64 (box64 x1)]
    | K2 (#(x0, x1), x2, x3) -> 2, [F (box_float x0); I32 (box32 x1); S x2; F (box_float x3)]
    | K3 (#(x0, x1), x2) -> 3, [S x0; S x1; I64 (box64 x2)]
    | K4 (#(x0, x1), x2, x3) -> 4, [F (box_float x0); I64 (box64 x1); S x2; S x3]
  let[@inline never] create seed i =
    { left = guard "left" seed; left_bits = #0xdead_beefl; data = make seed i;
      right_bits = #0x1234_5678_9abc_def0L; right = guard "right" seed }
  let[@inline never] replace cell seed i = cell.data <- make seed i
  let[@inline never] observe cell =
    cell.left, box32 cell.left_bits, read cell.data, box64 cell.right_bits, cell.right
  let () = exercise "V198" [|[Tagged]; [Fraction; Wide]; [Fraction; Narrow; Text; Fraction]; [Text; Text; Wide]; [Fraction; Wide; Text; Text]|] ~create ~replace ~observe
end

module V199 = struct
  type payload =
    | K0 of #(float# * int64_u) * string * string
    | K1 of int
  [@@unboxed]
  type cell = { left : string; left_bits : int32_u; mutable data : payload;
                right_bits : int64_u; right : string }
  let make seed = function
    | 0 -> K0 (#(unbox_float (fraction seed 0), unbox64 (wide seed 1)), text seed 2, text seed 3)
    | i -> assert (i = 1); K1 (number seed 0)
  let read = function
    | K0 (#(x0, x1), x2, x3) -> 0, [F (box_float x0); I64 (box64 x1); S x2; S x3]
    | K1 (x0) -> 1, [I x0]
  let[@inline never] create seed i =
    { left = guard "left" seed; left_bits = #0xdead_beefl; data = make seed i;
      right_bits = #0x1234_5678_9abc_def0L; right = guard "right" seed }
  let[@inline never] replace cell seed i = cell.data <- make seed i
  let[@inline never] observe cell =
    cell.left, box32 cell.left_bits, read cell.data, box64 cell.right_bits, cell.right
  let () = exercise "V199" [|[Fraction; Wide; Text; Text]; [Tagged]|] ~create ~replace ~observe
end
